CREATE OR REPLACE FUNCTION public.customer_entry_price(_user_id uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM public.customer_launch_waitlist WHERE user_id=_user_id AND joined_at<'2027-01-01T05:00:00Z'::timestamptz) THEN 10::numeric ELSE 20::numeric END $$;
COMMENT ON TABLE public.customer_launch_waitlist IS 'Private pre-launch customer registrations. Membership before 2027-01-01 05:00 UTC qualifies that account for $10 annual entry including renewals for life. No free access or creator-library entitlement.';